/**
 * A common tie implementation using note details for positioning
 */
internal class NoteTieGlyph: TieGlyph {
    internal var startNote: Note!

    internal var endNote: Note!

    internal var startNoteRenderer: LineBarRenderer? = nil

    internal var endNoteRenderer: LineBarRenderer? = nil

    public init(_ slurEffectId: String, _ startNote: Note, _ endNote: Note, _ forEnd: Bool) {
        super.init(slurEffectId, forEnd)
        self.startNote = startNote
        self.endNote = endNote
    }

    internal var isLeftHandTap: Bool {
        get {
            return self.startNote === self.endNote
        }
    }

    public override func getTieHeight(_ startX: Double, _ startY: Double, _ endX: Double, _ endY: Double) -> Double {
        if self.isLeftHandTap {
            return self.renderer.smuflMetrics.tieHeight
        }
        return super.getTieHeight(startX, startY, endX, endY)
    }

    internal override func calculateTieDirection() throws -> BeamDirection {
        switch try self.lookupStartBeatRenderer().getBeatDirection(self.startNote.beat) {
        case BeamDirection.Up:
            return BeamDirection.Down
        default:
            return BeamDirection.Up
        }
    }

    internal override func calculateStartX() throws -> Double {
        let startNoteRenderer: LineBarRenderer = try self.lookupStartBeatRenderer()
        if self.isLeftHandTap {
            return try self.calculateEndX() - startNoteRenderer.smuflMetrics.leftHandTabTieWidth
        }
        return try startNoteRenderer.x + startNoteRenderer.getNoteX(self.startNote, self.getStartNotePosition())
    }

    internal func getStartNotePosition() -> NoteXPosition {
        return NoteXPosition.Center
    }

    internal override func calculateStartY() throws -> Double {
        let startNoteRenderer: LineBarRenderer = try self.lookupStartBeatRenderer()
        if self.isLeftHandTap {
            return try startNoteRenderer.getNoteY(self.startNote, NoteYPosition.Center)
        }
        switch self.tieDirection {
        case BeamDirection.Up:
            return try startNoteRenderer.getNoteY(self.startNote, NoteYPosition.Top)
        default:
            return try startNoteRenderer.getNoteY(self.startNote, NoteYPosition.Bottom)
        }
    }

    internal override func calculateEndX() throws -> Double {
        let endNoteRenderer: LineBarRenderer? = try self.lookupEndBeatRenderer()
        if !TypeHelper.isTruthy(endNoteRenderer) {
            return try self.calculateStartY() + self.renderer.smuflMetrics.leftHandTabTieWidth
        }
        if self.isLeftHandTap {
            return try endNoteRenderer!.x + endNoteRenderer!.getNoteX(self.endNote, NoteXPosition.Left)
        }
        return try endNoteRenderer!.x + endNoteRenderer!.getNoteX(self.endNote, NoteXPosition.Center)
    }

    internal func getEndNotePosition() -> NoteXPosition {
        return NoteXPosition.Center
    }

    internal override func caclculateEndY() throws -> Double {
        let endNoteRenderer: LineBarRenderer? = try self.lookupEndBeatRenderer()
        if !TypeHelper.isTruthy(endNoteRenderer) {
            return try self.calculateStartY()
        }
        if self.isLeftHandTap {
            return try endNoteRenderer!.getNoteY(self.endNote, NoteYPosition.Center)
        }
        switch self.tieDirection {
        case BeamDirection.Up:
            return try endNoteRenderer!.getNoteY(self.endNote, NoteYPosition.Top)
        default:
            return try endNoteRenderer!.getNoteY(self.endNote, NoteYPosition.Bottom)
        }
    }

    internal override func lookupEndBeatRenderer() throws -> LineBarRenderer? {
        if !TypeHelper.isTruthy(self.endNoteRenderer) {
            try self.endNoteRenderer = (jsNonNull(self.renderer.scoreRenderer.layout).getRendererForBar(jsNonNull(self.renderer.staff).staffId, self.endNote.beat.voice.bar) as? LineBarRenderer)
        }
        return self.endNoteRenderer
    }

    internal override func lookupStartBeatRenderer() throws -> LineBarRenderer {
        if !TypeHelper.isTruthy(self.startNoteRenderer) {
            try self.startNoteRenderer = jsCast(jsNonNull(jsNonNull(self.renderer.scoreRenderer.layout).getRendererForBar(jsNonNull(self.renderer.staff).staffId, self.startNote.beat.voice.bar)), LineBarRenderer.self)
        }
        return self.startNoteRenderer!
    }

    internal override func shouldDrawBendSlur() -> Bool {
        return false
    }
}

/**
 * A tie glyph for continued multi-system ties/slurs
 */
internal final class ContinuationTieGlyph: TieGlyph {
    private var _startTie: TieGlyph!

    public init(_ startTie: TieGlyph) {
        super.init(startTie.slurEffectId, false)
        self._startTie = startTie
    }

    internal override func lookupStartBeatRenderer() throws -> LineBarRenderer {
        return try jsCast(self.renderer, LineBarRenderer.self)
    }

    internal override func lookupEndBeatRenderer() throws -> LineBarRenderer {
        return try jsCast(self.renderer, LineBarRenderer.self)
    }

    internal override func shouldDrawBendSlur() -> Bool {
        return false
    }

    internal override func calculateTieDirection() -> BeamDirection {
        return self._startTie.tieDirection
    }

    internal override func calculateStartY() throws -> Double {
        return try self._startTie.calculateMultiSystemSlurY(self.renderer)
    }

    internal override func caclculateEndY() throws -> Double {
        return try self.calculateStartY()
    }

    internal override func calculateStartX() throws -> Double {
        let first: BarRendererBase = try jsNonNull(self.renderer.staff).barRenderers[0]
        return first.x + first.beatGlyphsStart - 2.0 * first.smuflMetrics.oneStaffSpace
    }

    internal override func calculateEndX() throws -> Double {
        let last: BarRendererBase = try jsNonNull(self.renderer.staff).barRenderers[try (jsNonNull(self.renderer.staff).barRenderers.length - 1.0).toInt()]
        return last.x + last.width
    }
}
